/**
 * Proves what was sent and what bounced. **Nobody should assume a mail
arrived that never did**, which is why delivery status is visible in the
product rather than buried in a provider dashboard.

 * @summary Mail delivery log for this ticket
 */
export const listTicketEmailsPathTicketIdRegExp = new RegExp('^[A-Z][A-Z0-9]{1,9}-\\d{2}-\\d{5,}$');


export const listTicketEmailsParams = zod.object({
  "ticketId": zod.string().regex(listTicketEmailsPathTicketIdRegExp)
})

export const listTicketEmailsQueryLimitDefault = 50;
export const listTicketEmailsQueryLimitMax = 200;



export const listTicketEmailsQueryParams = zod.object({
  "cursor": zod.string().optional().describe('Opaque cursor from `meta.nextCursor`. Never an offset.'),
  "limit": zod.number().min(1).max(listTicketEmailsQueryLimitMax).default(listTicketEmailsQueryLimitDefault)
})

export const listTicketEmailsResponse = zod.object({
  "data": zod.array(zod.object({
  "id": zod.number().optional(),
  "toAddress": zod.string().email().optional(),
  "subject": zod.string().optional(),
  "eventKey": zod.string().optional(),
  "status": zod.enum(['QUEUED', 'SENT', 'BOUNCED', 'FAILED']).optional(),
  "retryCount": zod.number().optional(),
  "nextAttemptAt": zod.string().datetime({}).nullish(),
  "providerMessageId": zod.string().nullish(),
  "sentAt": zod.string().datetime({}).nullish()
})),
  "meta": zod.object({
  "nextCursor": zod.string().nullish(),
  "hasMore": zod.boolean().optional(),
  "totalCount": zod.number().nullish().describe('Present only where a count is cheap. Never computed live over tickets.')
}).optional()
})

/**
 * Posts a structured message into the ticket thread with
`[Reply with update]` and `[Open Quick Update]` actions. **The manager's
response time is recorded as a reportable metric** — the round trip is the
thing worth measuring, not just the ask.

 * @summary Request a status update from the assignee
 */
export const askTicketStatusPathTicketIdRegExp = new RegExp('^[A-Z][A-Z0-9]{1,9}-\\d{2}-\\d{5,}$');


export const askTicketStatusParams = zod.object({
  "ticketId": zod.string().regex(askTicketStatusPathTicketIdRegExp)
})

export const askTicketStatusBodyNoteMax = 1000;



export const askTicketStatusBody = zod.object({
  "note": zod.string().max(askTicketStatusBodyNoteMax).optional()
})

